    \item If $H$ is an induced minor of $G$, then $\alpha(H) \leqslant \alpha(G)$. (If $\eta: V(H) \to 2^{V(G)}$ is an induced minor model of $H$ in $G$, given an independent set $S \subseteq V(H)$, for each $x \in S$, choose a vertex $v_x \in \eta(x)$. Then $\{v_x: x \in S\}$ is an independent set in $G$.)
    \item If $H'$ is a minor of $G$, then there is an induced minor $H$ of $G$ such that $H'$ is a subgraph of $H$ with $V(H) = V(H')$.
\end{itemize}

